using System.Text;using System.Text.Json;using NotificationWorker.Events;using RabbitMQ.Client;using RabbitMQ.Client.Events;namespace NotificationWorker.Consumers;public sealed class RegistrationNotificationConsumer(ILogger<RegistrationNotificationConsumer> logger,IConfiguration configuration):BackgroundService{protected override async Task ExecuteAsync(CancellationToken stoppingToken){var factory=new ConnectionFactory{HostName=configuration["RabbitMq:Host"]??"rabbitmq",UserName=configuration["RabbitMq:User"]??"guest",Password=configuration["RabbitMq:Password"]??"guest",DispatchConsumersAsync=true,AutomaticRecoveryEnabled=true,NetworkRecoveryInterval=TimeSpan.FromSeconds(5)};while(!stoppingToken.IsCancellationRequested){try{using var connection=factory.CreateConnection();using var channel=connection.CreateModel();logger.LogInformation("Connected to RabbitMQ.");channel.QueueDeclare("registration.created",durable:true,exclusive:false,autoDelete:false);channel.BasicQos(0,1,false);var consumer=new AsyncEventingBasicConsumer(channel);consumer.Received+=async(_,args)=>{try{var json=Encoding.UTF8.GetString(args.Body.ToArray());var message=JsonSerializer.Deserialize<RegistrationCreatedEvent>(json)??throw new InvalidOperationException("Invalid registration event.");logger.LogInformation("NOTIFICATION: Registration {RegistrationId} for {CandidateName} ({CandidateNumber}), session {ExamSession}, subjects {Subjects}",message.RegistrationId,message.CandidateName,message.CandidateNumber,message.ExamSession,message.Subjects);channel.BasicAck(args.DeliveryTag,false);}catch(Exception ex){logger.LogError(ex,"Could not process registration event; requeueing.");channel.BasicNack(args.DeliveryTag,false,true);}await Task.CompletedTask;};channel.BasicConsume("registration.created",autoAck:false,consumer);logger.LogInformation("Listening for registration.created events.");while(!stoppingToken.IsCancellationRequested&&connection.IsOpen&&channel.IsOpen)await Task.Delay(1000,stoppingToken);}catch(OperationCanceledException)when(stoppingToken.IsCancellationRequested){break;}catch(Exception ex){logger.LogError(ex,"Notification Worker connection failed. Retrying in 5 seconds.");await Task.Delay(TimeSpan.FromSeconds(5),stoppingToken);}}}}